cat > StackRightDC1LayoutScenario.ts <<'EOF'
// DC1: at start the pallet is on the floor about 1 m ahead at real size, and the shelf bay
// with 8 cartons is about 1.4 m to the right.
import {Scenario} from "Leaf.lspkg/Scenarios/scenario/Scenario"
import {expect} from "Leaf.lspkg/Utils/common/Expect"
import {findSceneObjectByName, sleep} from "Leaf.lspkg/Utils/common/Utils"
import {getController, freshPallet} from "./StackRightLeafHelpers"

@component
export class StackRightDC1LayoutScenario extends Scenario {
  async run(): Promise<void> {
    await sleep(1500)
    const c = getController()
    await freshPallet(c)
    const cam = c.getCameraWorldPosition()
    const pallet = c.getPalletWorldPosition()
    const shelf = c.getShelfWorldPosition()

    // Pallet: ~100 cm ahead (-z), roughly centred, on the floor (140-170 cm below the eyes).
    expect(cam.z - pallet.z).toBeGreaterThan(80)
    expect(cam.z - pallet.z < 120).toBe(true)
    expect(Math.abs(pallet.x - cam.x) < 20).toBe(true)
    const drop = cam.y - pallet.y
    expect(drop >= 140 && drop <= 170).toBe(true)

    // Shelf bay: ~140 cm to the right (+x).
    const right = shelf.x - cam.x
    expect(right >= 120 && right <= 160).toBe(true)

    // 8 cartons on the shelf, none placed, all inside the shelf bay's footprint (60 D x 240 W).
    expect(c.getCartonCount()).toBe(8)
    for (let i = 0; i < 8; i++) {
      expect(c.isCartonPlaced(i)).toBe(false)
      const p = c.getCartonWorldPosition(i)
      expect(Math.abs(p.x - shelf.x) <= 30).toBe(true)
      expect(Math.abs(p.z - shelf.z) <= 120).toBe(true)
      expect(p.y > shelf.y + 35).toBe(true)
    }

    // Named scene objects exist; the stand-in pick list is obvious in the hierarchy.
    expect(findSceneObjectByName("Pallet") != null).toBe(true)
    expect(findSceneObjectByName("ShelfBay") != null).toBe(true)
    expect(findSceneObjectByName("PickList (stand-in for barcode scan)") != null).toBe(true)
    expect(c.getCounterText()).toBe("0 / 8")
  }
}
EOF
cat > StackRightDC2GhostScenario.ts <<'EOF'
// DC2: grabbing the correct next carton shows its ghost on the pallet with the tag
// "Layer N · Heavy/Light · kg". A wrong carton shows no ghost.
import {Scenario} from "Leaf.lspkg/Scenarios/scenario/Scenario"
import {expect} from "Leaf.lspkg/Utils/common/Expect"
import {sleep} from "Leaf.lspkg/Utils/common/Utils"
import {getController, freshPallet, settle} from "./StackRightLeafHelpers"

@component
export class StackRightDC2GhostScenario extends Scenario {
  async run(): Promise<void> {
    await sleep(1500)
    const c = getController()
    await freshPallet(c)

    expect(c.isGhostVisible()).toBe(false)
    expect(c.isCartonGlowing(0)).toBe(true)

    // Wrong carton grabbed: no ghost.
    c.simulateGrab(3)
    await sleep(200)
    expect(c.isGhostVisible()).toBe(false)
    c.simulateRelease(3, c.getCartonHomePosition(3))
    await settle(c)

    // Correct carton grabbed: ghost on its slot, tag text.
    c.simulateGrab(0)
    await sleep(200)
    expect(c.isGhostVisible()).toBe(true)
    expect(c.getGhostTagText()).toBe("Layer 1 · Heavy · 14 kg")
    const g = c.getGhostWorldPosition()
    const s = c.getSlotWorldPosition(0)
    expect(g.distance(s) < 1).toBe(true)
    // Ghost sits inside the pallet footprint.
    const p = c.getPalletWorldPosition()
    expect(Math.abs(g.x - p.x) <= 58.25).toBe(true)
    expect(Math.abs(g.z - p.z) <= 58.25).toBe(true)

    // Releasing off the pallet hides the ghost and costs no mistake.
    const before = c.getMistakes()
    c.simulateRelease(0, c.getCartonHomePosition(0))
    await settle(c)
    expect(c.isGhostVisible()).toBe(false)
    expect(c.getMistakes()).toBe(before)
  }
}
