    const cam = c.getCameraWorldPosition()
    const pallet = c.getPalletWorldPosition()
    const shelf = c.getShelfWorldPosition()

    // Pallet: ~100 cm ahead (-z), roughly centred, on the floor (140-170 cm below the eyes).
    const ahead = cam.z - pallet.z
    expect(ahead >= 80 && ahead <= 120).toBe(true)
    expect(Math.abs(pallet.x - cam.x) < 20).toBe(true)
    const drop = cam.y - pallet.y
    expect(drop >= 140 && drop <= 170).toBe(true)

    // Shelf bay: ~140 cm to the right (+x).
    const right = shelf.x - cam.x
    expect(right >= 120 && right <= 160).toBe(true)

    // 8 cartons on the shelf, none placed, all inside the shelf bay's footprint (60 D x 240 W).
    expect(c.getCartonCount()).toBe(8)
    for (let i = 0; i < 8; i++) {
      expect(c.isCartonPlaced(i)).toBe(false)
      const p = c.getCartonWorldPosition(i)
      expect(Math.abs(p.x - shelf.x) <= 30).toBe(true)
      expect(Math.abs(p.z - shelf.z) <= 120).toBe(true)
      expect(p.y > shelf.y + 35).toBe(true)
    }

    // Named scene objects exist; the stand-in pick list is obvious in the hierarchy.
    expect(findSceneObjectByName("Pallet") != null).toBe(true)
    expect(findSceneObjectByName("ShelfBay") != null).toBe(true)
    expect(findSceneObjectByName("PickList (stand-in for barcode scan)") != null).toBe(true)
    expect(c.getCounterText()).toBe("0 / 8")
  }
}

// DC2: grabbing the correct next carton shows its ghost on the pallet with the tag
// "Layer N · Heavy/Light · kg". A wrong carton shows no ghost.
import {Scenario} from "Leaf.lspkg/Scenarios/scenario/Scenario"
import {expect} from "Leaf.lspkg/Utils/common/Expect"
import {sleep} from "Leaf.lspkg/Utils/common/Utils"
import {getController, freshPallet, settle} from "./StackRightLeafHelpers"

@component
export class StackRightDC2GhostScenario extends Scenario {
  async run(): Promise<void> {
    await sleep(1500)
    const c = getController()
    await freshPallet(c)

    expect(c.isGhostVisible()).toBe(false)
    expect(c.isCartonGlowing(0)).toBe(true)

    // Wrong carton grabbed: no ghost. Put it back off the pallet (no mistake).
    c.simulateGrab(3)
    await sleep(200)
    expect(c.isGhostVisible()).toBe(false)
    c.simulateRelease(3, c.getCartonHomePosition(3))
    await settle(c)

    // Correct carton grabbed: ghost on its slot, tag text.
    c.simulateGrab(0)
    await sleep(200)
    expect(c.isGhostVisible()).toBe(true)
    expect(c.isGhostTagVisible()).toBe(true)
    expect(c.getGhostTagText()).toBe("Layer 1 · Heavy · 14 kg")
    const g = c.getGhostWorldPosition()
    expect(g.distance(c.getSlotWorldPosition(0)) < 1).toBe(true)
    const p = c.getPalletWorldPosition()
    expect(Math.abs(g.x - p.x) <= 58.25).toBe(true)
    expect(Math.abs(g.z - p.z) <= 58.25).toBe(true)

    // Releasing off the pallet hides the ghost and costs no mistake.
    const before = c.getMistakes()
    c.simulateRelease(0, c.getCartonHomePosition(0))
    await settle(c)
    expect(c.isGhostVisible()).toBe(false)
    expect(c.getMistakes()).toBe(before)
  }
}

// DC5: after all 8 cartons the completion card shows on the pallet with time and mistakes,
// and Reset (pinched through real SIK input) clears the pallet.
import {Scenario} from "Leaf.lspkg/Scenarios/scenario/Scenario"
import {expect} from "Leaf.lspkg/Utils/common/Expect"
import {findSceneObjectByName, sleep} from "Leaf.lspkg/Utils/common/Utils"
import {DefaultLeafInteractor} from "Leaf.lspkg/Interactors/interactor/DefaultLeafInteractor"
import {findInteractablesByName} from "Leaf.lspkg/Interactors/InteractableUtils"
import {getController, freshPallet, dropOnSlot, settle, resetButtonFaceName} from "./StackRightLeafHelpers"

@component
export class StackRightDC5CompleteResetScenario extends Scenario {
  async run(): Promise<void> {
    await sleep(1500)
    const c = getController()
    await freshPallet(c)

    // One deliberate mistake (eggs while heavy is due), then a clean build of all 8.
    c.simulateGrab(6)
    c.simulateRelease(6, c.getPalletWorldPosition().add(new vec3(0, 60, 0)))
    await settle(c)
    for (let i = 0; i < 8; i++) {
      dropOnSlot(c, i)
      await sleep(100)
      expect(c.isCartonPlaced(i)).toBe(true)
    }
    expect(c.isComplete()).toBe(true)
    expect(c.getCounterText()).toBe("8 / 8")
    expect(c.isCompletionVisible()).toBe(true)
    const card = c.getCompletionText()
    expect(card.includes("Time ")).toBe(true)
    expect(card.includes("Mistakes 1")).toBe(true)
    expect(card.includes("Wrap and label")).toBe(true)

    // Card stays up.
    await sleep(1000)
    expect(c.isCompletionVisible()).toBe(true)

    // Reset via the real UIKit button.
    const resetRoot = findSceneObjectByName("ResetButton")
    const btn = findInteractablesByName(resetButtonFaceName(), undefined, true)
      .filter((b) => b.getSceneObject().getParent() === resetRoot)[0]
    if (!btn) throw new Error("Reset button interactable not found")
    await new DefaultLeafInteractor().trigger(btn)
    await sleep(400)

    expect(c.isCompletionVisible()).toBe(false)
    expect(c.getPlacedCount()).toBe(0)
    expect(c.getMistakes()).toBe(0)
    expect(c.getCounterText()).toBe("0 / 8")
    for (let i = 0; i < 8; i++) {
      expect(c.isCartonPlaced(i)).toBe(false)
      expect(c.getCartonWorldPosition(i).distance(c.getCartonHomePosition(i)) < 1).toBe(true)
    }
    expect(c.isCartonGlowing(0)).toBe(true)
  }
}

// Reachability: a standing user can physically pinch the Reset button (IK arm + head).
import {Scenario} from "Leaf.lspkg/Scenarios/scenario/Scenario"
import {expect} from "Leaf.lspkg/Utils/common/Expect"
import {findSceneObjectByName, sleep} from "Leaf.lspkg/Utils/common/Utils"
import {findInteractablesByName} from "Leaf.lspkg/Interactors/InteractableUtils"
import {createIKInteractor} from "Leaf.lspkg/Interactors/interactor/ik/visualizer/BitmojiAvatar"
import {getController, dropOnSlot, resetButtonFaceName} from "./StackRightLeafHelpers"

@component
export class StackRightResetReachIKScenario extends Scenario {
  private readonly ik = createIKInteractor()

  async run(): Promise<void> {
    await sleep(1500)
    const c = getController()
    c.reset()
    dropOnSlot(c, 0)
    expect(c.getPlacedCount()).toBe(1)

    const resetRoot = findSceneObjectByName("ResetButton")
    const btn = findInteractablesByName(resetButtonFaceName(), undefined, true)
      .filter((b) => b.getSceneObject().getParent() === resetRoot)[0]
    if (!btn) throw new Error("Reset button interactable not found")
    await this.ik.trigger(btn)
    await sleep(400)
    expect(c.getPlacedCount()).toBe(0)
  }
}
